import re, math
def node_by_title(doc, title):
    for n in doc["nodes"]:
        if n["title"] == title:
            return n
    return None

def table_rows(node):
    rows = []
    for i, row in enumerate(node["table"]["rows"]):
        rows.append((i, dict(zip(node["table"]["columns"], row))))
    return rows

def motion_rows_for_object(node, oid):
    return [r for _, r in table_rows(node) if r["object"].split()[0] == oid]

def get_position_at_time(node, oid, frame):
    rows = motion_rows_for_object(node, oid)
    # try direct match
    for r in rows:
        if int(r["frame"]) == frame:
            return float(r["x"]), float(r["y"])
    # interpolate
    if not rows:
        return None, None
    rows.sort(key=lambda r: int(r["frame"]))
    if frame < int(rows[0]["frame"]) or frame > int(rows[-1]["frame"]):
        return None, None
    prev = None
    next_ = None
    for r in rows:
        fr = int(r["frame"])
        if fr == frame:
            return float(r["x"]), float(r["y"])
        if fr < frame:
            prev = r
        if fr > frame:
            next_ = r
            break
    if prev is None or next_ is None:
        return None, None
    t0, t1 = int(prev["frame"]), int(next_["frame"])
    ratio = (frame - t0) / (t1 - t0)
    x0, y0 = float(prev["x"]), float(prev["y"])
    x1, y1 = float(next_["x"]), float(next_["y"])
    return x0 + ratio * (x1 - x0), y0 + ratio * (y1 - y0)

