# 2. Estimate a global collision distance threshold from all recorded collision events
def estimate_threshold_from_doc(doc):
    dmin = float("inf")
    for node in doc["nodes"]:
        if not node["title"].startswith("Video "):
            continue
        events_node = node_by_title(doc, f"{node['title']}: Events")
        if events_node is None:
            continue
        motion_node = node_by_title(doc, f"{node['title']}: Motion log")
        if motion_node is None:
            continue
        for li, line in enumerate(events_node["lines"]):
            m_coll = re.search(
                r"Frame (\d+): Object (\d+).*collides with Object (\d+)", line
            )
            if not m_coll:
                continue
            frame = int(m_coll.group(1))
            oid1, oid2 = m_coll.group(2), m_coll.group(3)
            pos1 = get_position_at_time(motion_node, oid1, frame)
            pos2 = get_position_at_time(motion_node, oid2, frame)
            if pos1[0] is None or pos2[0] is None:
                continue
            dx = pos2[0] - pos1[0]
            dy = pos2[1] - pos1[1]
            d = math.hypot(dx, dy)
            if d < dmin:
                dmin = d
    if dmin == float("inf"):
        dmin = 0.1
    return dmin

threshold_est = estimate_threshold_from_doc(doc)
print("\nEstimated collision distance threshold (raw) =", threshold_est)
print("Threshold used in simulation (buffered) =", threshold_est * 1.1)

